CREATE FUNCTION public.reorder_production_modules(module_ids uuid[]) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE n integer; lvl text; BEGIN IF NOT (public.is_admin() OR public.is_production_instructor(auth.uid())) THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT level INTO lvl FROM public.production_modules WHERE id=module_ids[1]; IF lvl IS NULL OR (SELECT count(*) FROM public.production_modules WHERE level=lvl)<>cardinality(module_ids) OR (SELECT count(DISTINCT x) FROM unnest(module_ids) x)<>cardinality(module_ids) THEN RAISE EXCEPTION 'Invalid module order'; END IF; FOR n IN 1..cardinality(module_ids) LOOP UPDATE public.production_modules SET order_index=n WHERE id=module_ids[n] AND level=lvl; IF NOT FOUND THEN RAISE EXCEPTION 'Module cannot be moved'; END IF; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.reorder_production_modules(uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reorder_production_modules(uuid[]) TO authenticated,service_role;
CREATE POLICY production_instructor_profile_read ON public.profiles FOR SELECT TO authenticated USING(public.is_production_instructor(auth.uid()) AND EXISTS(SELECT 1 FROM public.production_enrollments e WHERE e.student_id=profiles.id AND e.instructor_id=auth.uid() AND e.active));